def renumber(program):
    new_number = {}
    for i, line in enumerate(program):
        old = line.split(" ", 1)[0]
        new_number[old] = str((i + 1) * 10)
    out = []
    for line in program:
        old, rest = line.split(" ", 1)
        words = rest.split(" ")
        for j in range(1, len(words)):
            if words[j - 1] in ("GOTO", "THEN") and words[j] in new_number:
                words[j] = new_number[words[j]]
        out.append(new_number[old] + " " + " ".join(words))
    return out

unitTests:
@test("lines are renumbered in tens")
def _():
    check_eq(renumber(['5 PRINT "HI"', '7 GOTO 5']), ['10 PRINT "HI"', '20 GOTO 10'])

@test("jumps follow their lines")
def _():
    program = [
        "100 INPUT N",
        "105 IF N = 0 THEN 200",
        "110 PRINT N",
        "150 GOTO 100",
        "200 END",
    ]
    check_eq(renumber(program), [
        "10 INPUT N",
        "20 IF N = 0 THEN 50",
        "30 PRINT N",
        "40 GOTO 10",
        "50 END",
    ])

@test("a jump to nowhere stays")
def _():
    check_eq(renumber(["1 GOTO 99", "2 END"]), ["10 GOTO 99", "20 END"])

